#!/usr/bin/env node
/**
 * Builds cxsite/lib/legal/bundle.generated.ts from every .md file in
 * apps/customer_app/legal/. Single source of truth: the markdown lives
 * with the customer app, and the website reads the same files at build
 * time. Update one file -> both apps + website show the update on next
 * release.
 *
 * Wired via cxsite/package.json prebuild:
 *   "prebuild": "node lib/legal/build-bundle.mjs"
 *
 * Run manually:
 *   node lib/legal/build-bundle.mjs
 */
import { readdirSync, readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join, resolve } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));

// cxsite/lib/legal -> repo root -> apps/customer_app/legal
const LEGAL_SRC_DIR = resolve(__dirname, "../../../apps/customer_app/legal");
const OUT_FILE = join(__dirname, "bundle.generated.ts");

const EXCLUDED = new Set(["INDEX.md", "CHANGELOG.md"]);

if (!existsSync(LEGAL_SRC_DIR)) {
  console.error(`[cxsite/legal] source dir not found: ${LEGAL_SRC_DIR}`);
  process.exit(1);
}

const files = readdirSync(LEGAL_SRC_DIR)
  .filter((f) => f.endsWith(".md") && !EXCLUDED.has(f))
  .sort();

if (files.length === 0) {
  console.error(`[cxsite/legal] no .md files in ${LEGAL_SRC_DIR}`);
  process.exit(1);
}

const entries = files.map((file) => {
  const body = readFileSync(join(LEGAL_SRC_DIR, file), "utf8");
  return `  ${JSON.stringify(file)}: ${JSON.stringify(body)}`;
});

const totalBytes = entries.reduce((n, e) => n + e.length, 0);

const out = `/**
 * AUTO-GENERATED by lib/legal/build-bundle.mjs — do not edit by hand.
 *
 * Source: apps/customer_app/legal/*.md (${files.length} documents, ~${Math.round(totalBytes / 1024)} KB).
 * Regenerate: \`node lib/legal/build-bundle.mjs\` or rebuild cxsite.
 */
export const LEGAL_BUNDLE: Record<string, string> = {
${entries.join(",\n")}
};
`;

mkdirSync(dirname(OUT_FILE), { recursive: true });
writeFileSync(OUT_FILE, out, "utf8");

console.log(
  `[cxsite/legal] wrote ${OUT_FILE.replace(/.*cxsite./, "cxsite/")} (${files.length} docs, ${Math.round(totalBytes / 1024)} KB)`,
);
